Section FPX_1. Context {fx : PropExec.FPState}.
Variable scfg : SpuriousCfg.

Section DrvLayoutA.
  Variable L : asan_layout.
  Variable ar : asan_run.
  Variable C : asan_statics_cells.
  Variable IL : icpt_layout.
  Variable HI : asan_iface.
  Hypothesis HIok : asan_iface_okB L ar C scfg HI.
  Variable sp0 : word.
  Hypothesis Hsp : 0x7fff80000000 <= bv_unsigned sp0 <= 2 ^ 47.
  Hypothesis Hal : bv_unsigned sp0 mod 16 = 0.

  (* [comment removed for export] *)
  Record drv_layoutA : Prop := DLA {
    dla_segs : hl_segs L = ASEGS;
    dla_malloc : hl_malloc L = 0x7a9c4; dla_free : hl_free L = 0x7a9c0; dla_memcpy : icl_memcpy IL = 0x78e3c;
    dla_tp : hl_tp L = 0x67a180;
    dla_img_lo : hl_img_lo L = 0x10000; dla_img_hi : hl_img_hi L = 0x69c000;
    dla_sptop : ar_sptop ar = bv_unsigned sp0;
    dla_scr : 0 <= hl_scr_malloc L <= 4096 /\ 0 <= hl_scr_free L <= 4096 /\ 0 <= hl_scr_mem L <= 4096;
    (* [comment removed for export] *)
    dla_client : forall lo hi a, In (lo, hi) IMG_CLIENT_A -> lo <= a < hi -> ~ hl_rt_static L a;
    (* [comment removed for export] *)
    dla_ro : forall lo hi a, In (lo, hi) IMG_W_A -> lo <= a < hi -> ~ hl_rt_ro L a;
    dla_ro_img : forall a, hl_rt_ro L a -> 0x10000 <= a < 0x69c000
  }.
  Hypothesis DL : drv_layoutA.

  Lemma wseg_stage : wseg_ok ASEGS (Z_to_bv 64 0x668750) 65536 = true.
Proof.
ltac2:(KReplay.run1 (kr_t_Eb0DrvLib ()) ["FPX_1"; "DrvLayoutA"] "p;2p;1p;3g00;=j2=Tg00;Wj17Tg00<5j10Tg00<Zj12Tg00=?j1;Tg00=]j2:Tg00>Cj13Tg00>aj16Tg00??j14Tg00?]j15Tg00@:j18Tg00@Yj39Tg007Vj3<Tf0#2#2p=1g00AeR0g00BER1'=g00Beg00D7R2#1#1#1#7%02#1#0#0#2#0#1#1#0#0#0#2#0#2#0#1#1#;':g00D\#3#6#4#4#3#5#839=<01do"). Qed.

  (* [comment removed for export] *)
  Lemma vis_of_inv : forall LB FF LK cr A M model a,
    ri_inv HI LB FF LK cr A M (vml_of model) -> 0 <= a < 2 ^ 64 ->
    (a < 0x69c000 \/ bv_unsigned sp0 - 8388608 <= a \/ in_block LB a) ->
