    dinv LB LK cr A M model ->
    (forall a, 0 <= a < 2 ^ 64 -> ~ CWA LB a -> M' (Z_to_bv 64 a) = M (Z_to_bv 64 a)) ->
    (forall a : word, M a <> None -> M' a <> None) ->
    vml_of model' = vml_of model -> MInv A model' -> m_halted model' = None ->
    dinv LB LK cr A M' model'.
